class Solution {
public:
    int minDayskVariants(vector<vector<int>>& points, int k) {
        int ans = INT_MAX;
        int n = points.size();
        vector<int> dists(n);
        for (int x = 1; x <= 100; x++) {
            for (int y = 1; y <= 100; y++) {
                for (int i = 0; i < n; i++) {
                    dists[i] = abs(x - points[i][0]) + abs(y - points[i][1]);
                }
                nth_element(dists.begin(), dists.begin() + k - 1, dists.end());
                ans = min(ans, dists[k - 1]);
            }
        }
        return ans;
    }
};

class Solution {
    public int minDayskVariants(int[][] points, int k) {
        int ans = Integer.MAX_VALUE;
        int n = points.length;
        int[] dists = new int[n];
        for (int x = 1; x <= 100; x++) {
            for (int y = 1; y <= 100; y++) {
                for (int i = 0; i < n; i++) {
                    dists[i] = Math.abs(x - points[i][0]) + Math.abs(y - points[i][1]);
                }
                java.util.Arrays.sort(dists);
                ans = Math.min(ans, dists[k - 1]);
            }
        }
        return ans;
    }
}

var minDayskVariants = function(points, k) {
  let ans = Infinity;
  const n = points.length;
  for (let x = 1; x <= 100; x++) {
    for (let y = 1; y <= 100; y++) {
      const dists = points.map(p => Math.abs(x - p[0]) + Math.abs(y - p[1]));
      dists.sort((a, b) => a - b);
      if (dists[k - 1] < ans) ans = dists[k - 1];
    }
  }
  return ans;
};
